-- ============================================================================
-- scripts/reconcile_THE_PIG_DEV1.sql (DEV1 copy: every target object reads DEV1; CLN sources unchanged)
-- M6 deliverable (build 21: + FIN_PL_MONTHLY P&L and REF_ACCOUNTS; pacing as before). Read-only. Never deployed.
-- For every source table of lane THE_PIG, compares row count and the sum of
-- every numeric column across
--   CLN   CLN.BOX_INVESTMENT_DATA source table
--   STG   its staging table
--   XFRM  the four H1-routed streams (facts) or PACING (pace tables), by SOURCE_TABLE
--   SEM   the six semantic tables (facts), by SOURCE_TABLE
-- A layer that does not carry a metric shows null and is not compared.
-- PASS when every carried layer is within 0.005 of CLN; FAIL otherwise.
-- The last row is the total failure count. Zero is required.
-- CLN column names are taken from the deployed staging code: facts ACTUAL_AMOUNT
-- -> SOURCE_AMOUNT (AMT) or STAT_VALUE (STAT, statistic rows); pace tables carry
-- every source column verbatim.
-- ============================================================================
declare
    res resultset;
begin
    res := (
    with
    m as (
        -- P&L fact (build 21): x2, AMT / STAT split by the staged statistic lines
        select 'PIG_HOTELS_FIN_PL_MONTHLY' t, 'CLN' l, object_construct('ROWS', count(*) * 2, 'AMT', coalesce(sum(iff(account_line_number in ('C00001-050','C00008-050','C00010-050'), 0, coalesce(actual_amount,0)+coalesce(forecast_amount,0))),0), 'STAT', coalesce(sum(iff(account_line_number in ('C00001-050','C00008-050','C00010-050'), coalesce(actual_amount,0)+coalesce(forecast_amount,0), 0)),0), 'BUDGET_AMOUNT', coalesce(sum(budget_amount),0)) o from CLN.BOX_INVESTMENT_DATA.CLN_PIG_HOTELS_FIN_PL_MONTHLY
