        select 'PIG_HOTELS_FIN_PL_MONTHLY', 'XFRM', object_construct('ROWS', count(*), 'AMT', coalesce(sum(source_amount),0), 'STAT', coalesce(sum(stat_value),0)) from (select source_table, source_amount, stat_value from DEV1.TRANSFORMATION.XFRM_THE_PIG_INCOME_STATEMENT union all select source_table, source_amount, stat_value from DEV1.TRANSFORMATION.XFRM_THE_PIG_BALANCE_SHEET union all select source_table, source_amount, stat_value from DEV1.TRANSFORMATION.XFRM_THE_PIG_OPERATING_METRICS union all select source_table, source_amount, stat_value from DEV1.TRANSFORMATION.XFRM_THE_PIG_UNKNOWN) where source_table = 'CLN.BOX_INVESTMENT_DATA.CLN_PIG_HOTELS_FIN_PL_MONTHLY'
